862	    /// Constructs that the current reasoning layer does not model precisely enough to let
863	    /// `NotReached` read as proof of absence.
864	    pub fn unmodeled_reasoning_construct(
865	        &self,
866	        node: &Node<'_>,
867	        source: &str,
868	    ) -> Option<&'static str> {
869	        let kind = node.kind();
870	        match self {
871	            Self::Rust => match kind {
872	                "try_expression" => Some("Rust ? operator"),
873	                "closure_expression" => Some("Rust closure"),
874	                _ => None,
875	            },
876	            Self::Go => match kind {
877	                "go_statement" => Some("Go go statement"),
878	                "send_statement" => Some("Go channel send"),
879	                "receive_statement" => Some("Go channel receive"),
880	                "select_statement" => Some("Go select"),
881	                "unary_expression" if node_text(source, node).trim_start().starts_with("<-") => {
882	                    Some("Go channel receive")
883	                }
884	                _ => None,
885	            },
886	            Self::JavaScript | Self::TypeScript | Self::Tsx => match kind {
887	                "await_expression" => Some("JS/TS await"),
888	                "yield_expression" => Some("JS/TS yield"),
889	                "arrow_function" | "function_expression" => Some("JS/TS callback"),
890	                "call_expression" => js_promise_handler_call(node, source),
891	                _ => None,
892	            },
893	            Self::Python => match kind {
894	                "decorated_definition" => Some("Python decorator"),
895	                "with_statement" => Some("Python with statement"),
896	                "yield" | "yield_expression" | "yield_from" => Some("Python yield"),
897	                "list_comprehension"
898	                | "dictionary_comprehension"
899	                | "set_comprehension"
900	                | "generator_expression" => Some("Python comprehension binding"),
901	                _ => None,
902	            },
903	            _ => None,
904	        }
905	    }
