907	    /// Get the function name node from a function definition.
908	    pub fn function_name<'a>(&self, node: &Node<'a>) -> Option<Node<'a>> {
909	        // Handle decorated definitions (Python)
910	        if node.kind() == "decorated_definition" {
911	            let mut cursor = node.walk();
912	            for child in node.children(&mut cursor) {
913	                if child.kind() == "function_definition" {
914	                    return child.child_by_field_name("name");
915	                }
916	            }
917	            return None;
918	        }
919	
920	        // Handle C/C++ template declarations
921	        if node.kind() == "template_declaration" {
922	            let mut cursor = node.walk();
923	            for child in node.children(&mut cursor) {
924	                if child.kind() == "function_definition" {
925	                    return find_identifier_in_c_function_def(&child);
926	                }
927	            }
928	            return None;
929	        }
930	
931	        // C/C++ function definitions have the name nested in a declarator chain
932	        if matches!(self, Self::C | Self::Cpp) && node.kind() == "function_definition" {
933	            return find_identifier_in_c_function_def(node);
934	        }
935	
936	        // Rust impl blocks: extract the type name
937	        if node.kind() == "impl_item" {
938	            return node.child_by_field_name("type");
939	        }
940	
941	        // Lua function_declaration: name is in "name" field
942	        // local_function: name is in "name" field
943	        // Bash function_definition: name field
944	        if matches!(self, Self::Lua) && node.kind() == "function_declaration" {
945	            let name = node.child_by_field_name("name")?;
946	            if matches!(
947	                name.kind(),
948	                "dot_index_expression" | "method_index_expression"
949	            ) {
950	                return name
951	                    .child_by_field_name("field")
952	                    .or_else(|| name.child_by_field_name("method"));
953	            }
954	            return Some(name);
955	        }
956	
957	        if matches!(self, Self::Bash) && node.kind() == "function_definition" {
958	            return node.child_by_field_name("name");
959	        }
960	
961	        // HCL block: return the logical name (second label) for unique identification.
962	        // e.g., resource "aws_instance" "web" -> "web" (not "aws_instance")
963	        // This avoids collisions when two resources share the same type.
964	        // The qualified name (aws_instance.web) is handled by TerraformRefGraph.
965	        if matches!(self, Self::Terraform) && node.kind() == "block" {
966	            let mut cursor = node.walk();
967	            let mut found_type = false;
968	            let mut first_label = None;
969	            for child in node.children(&mut cursor) {
970	                if child.kind() == "identifier" && !found_type {
971	                    found_type = true;
