495	/// Kind-aware combine for a receiver-typed candidate set (the PR-3 read-path core).
496	#[allow(dead_code)]
497	fn combine_kind<'a>(
498	    cands: &'a [FunctionId],
499	    facts: &BTreeMap<FunctionId, MethodFacts>,
500	    recovery: ReceiverRecovery,
501	    arg_count: Option<usize>,
502	    arg_spread: bool,
503	) -> Option<Vec<ResolvedCallee<'a>>> {
504	    let kept: Vec<&FunctionId> = cands
505	        .iter()
506	        .filter(|fid| {
507	            let Some(fact) = facts.get(*fid) else {
508	                return false;
509	            };
510	            fact.has_self
511	                && !matches!(
512	                    arg_count,
513	                    Some(n) if !arg_spread && fact.arity_excl_self != n
514	                )
515	        })
516	        .collect();
517	
518	    match kept.len() {
519	        0 => None,
520	        1 => {
521	            let fid = kept[0];
522	            let kind = receiver_resolution_kind(recovery);
523	            match facts.get(fid) {
524	                Some(MethodFacts {
525	                    kind: MethodKind::Inherent,
526	                    ..
527	                }) if recovery != ReceiverRecovery::StdWrapperPeel => Some(exact(kept, kind)),
528	                Some(_) => Some(demoted(kept, kind)),
529	                None => None,
530	            }
531	        }
532	        _ => Some(demoted(kept, ResolutionKind::TraitCha)),
533	    }
534	}
