540	impl CallGraph {
541	    fn rust_scope_graph_resolution(
542	        &self,
543	        graph: &ScopeGraph,
544	        site: &CallSite,
545	        file: FileId,
546	        from: ScopeId,
547	    ) -> Option<Vec<ResolvedCallee<'_>>> {
548	        // TODO: extract scope-graph bridge once the alias-target identity fix
549	        // has settled; keep this behavior-change PR narrowly scoped.
550	        let target = if site.callee_name.contains("::") {
551	            rust_graph_qualified_callable_edge(graph, site, file, from)
552	        } else if site.qualifier.is_none() {
553	            graph_callable_edge(graph, site)
554	        } else {
555	            return None;
556	        }?;
557	        self.graph_target_resolution(graph, site, &target)
558	    }
559	
560	    /// Does the authoritative graph resolve this `::` call's qualified-callable
561	    /// path to a free function (vs a method)? Used to divert free-function paths
562	    /// whose owner-segment name collides with a method bucket away from the
563	    /// owner-prune.
564	    fn rust_graph_qualified_target_is_free_fn(
565	        &self,
566	        graph: &ScopeGraph,
567	        site: &CallSite,
568	        file: FileId,
569	        from: ScopeId,
570	    ) -> bool {
571	        if !site.callee_name.contains("::") {
572	            return false;
573	        }
574	        let Some(target) = rust_graph_qualified_callable_edge(graph, site, file, from) else {
575	            return false;
576	        };
577	        let ids = self.graph_target_ids(graph, &target);
578	        !ids.is_empty() && ids.iter().all(|fid| !self.method_owners.contains_key(*fid))
579	    }
580	
581	    /// Owner-keyed disproof prune (spec §4). Fetch the bare `(owner, method)` pool
582	    /// from `self.methods`, run the `ScopeResolution` predicate, and decide:
583	    /// 1 survivor -> Exact; >1 -> demoted; unchanged from the bare pool -> `None`
584	    /// so the caller can fail-open to the #120 demote floor.
585	    fn rust_scope_prune_owner(
586	        &self,
587	        graph: &ScopeGraph,
588	        site: &CallSite,
589	        file: FileId,
590	        from: ScopeId,
591	        name: &str,
592	    ) -> Option<Vec<ResolvedCallee<'_>>> {
593	        let (owner, method) = owner_method_key(name)?;
594	        let pool_ids = self.methods.get(&(owner, method))?;
595	        let pool: Vec<&FunctionId> = pool_ids.iter().collect();
596	        let pred = ScopeResolution::new(self);
597	        let cx = crate::resolution_disproof::DisproofCx { graph, file, from };
598	        let pruned = crate::resolution_disproof::prune(
599	            pool.clone(),
600	            site,
601	            &cx,
602	            &[&pred as &dyn crate::resolution_disproof::DisproofPredicate],
603	        );
604	        if pruned.len() == pool.len() {
605	            return None;
606	        }
607	        Some(match pruned.len() {
608	            1 => exact(pruned, ResolutionKind::QualifiedOwner),
609	            _ => demoted(pruned, ResolutionKind::QualifiedOwner),
610	        })
611	    }
612	
613	    /// The in-repo `FunctionId`s a resolved callable `Target` maps to, applying
614	    /// the same per-binding file + owner narrowing `graph_target_resolution`
615	    /// uses. Shared by the `ScopeResolution` predicate and `graph_target_resolution`.
616	    fn graph_target_ids<'b>(&'b self, graph: &ScopeGraph, target: &Target) -> Vec<&'b FunctionId> {
617	        let mut ids: Vec<&FunctionId> = Vec::new();
618	        if !matches!(target, Target::Item { callable: true, .. }) {
619	            return ids;
620	        }
621	        for binding in graph.bindings.iter() {
622	            if !matches!(&binding.target, BindTarget::Resolved(t) if t == target) {
623	                continue;
624	            }
625	            let Some(file) = graph_file_for_scope(graph, binding.scope) else {
626	                continue;
627	            };
628	            let owner = graph_owner_name_for_scope(graph, binding.scope);
629	            if let Some(functions) = self.functions.get(&binding.name) {
630	                for fid in functions
631	                    .iter()
632	                    .filter(|fid| graph.file_paths.get(&fid.file).copied() == Some(file))
633	                {
634	                    match owner.as_deref() {
635	                        Some(owner)
636	                            if self.method_owners.get(fid).map(String::as_str) != Some(owner) =>
637	                        {
638	                            continue;
639	                        }
640	                        None if self.method_owners.contains_key(fid) => {
641	                            continue;
642	                        }
643	                        _ => {}
644	                    }
645	                    if !ids.contains(&fid) {
646	                        ids.push(fid);
647	                    }
648	                }
649	            }
650	        }
651	        ids
652	    }
653	
654	    fn graph_target_resolution(
655	        &self,
656	        graph: &ScopeGraph,
657	        site: &CallSite,
658	        target: &Target,
659	    ) -> Option<Vec<ResolvedCallee<'_>>> {
660	        let ids = self.graph_target_ids(graph, target);
661	        if ids.is_empty() {
662	            return None;
663	        }
664	        let qualified = site.callee_name.contains("::");
665	        match ids.len() {
666	            1 => {
667	                let kind = if qualified {
668	                    ResolutionKind::QualifiedOwner
669	                } else if ids[0].file == site.caller.file {
670	                    ResolutionKind::LocalDef
671	                } else {
672	                    ResolutionKind::FreeSingle
673	                };
674	                Some(exact(ids, kind))
675	            }
676	            _ => {
677	                // >1: a `::`-qualified owner that owns inherent + trait (or cfg
678	                // variants) demotes to NameOnly (recall-safe - keep every edge).
679	                // The unqualified LocalDef/FreeSingle arms stay singleton-only:
680	                // a >1 unqualified free-fn set routes through the existing free-fn
681	                // rungs, so decline here (return None) to fall through.
682	                if qualified {
683	                    Some(demoted(ids, ResolutionKind::QualifiedOwner))
684	                } else {
685	                    None
686	                }
687	            }
688	        }
689	    }
690	
691	    /// Owner-index lookup that knows whether the key is a multi-impl trait key.
692	    fn owner_lookup(&self, owner: &str, name: &str) -> Option<Vec<ResolvedCallee<'_>>> {
693	        let mut resolved = self.owner_lookup_in_modules(owner, name, &[])?;
