            if let Some(owner) = self.method_owners.get(caller) {
                if caller.file.ends_with(".java")
                    || caller.file.ends_with(".cpp")
                    || caller.file.ends_with(".cc")
                    || caller.file.ends_with(".cxx")
                    || caller.file.ends_with(".hpp")
                    || caller.file.ends_with(".h")
