                end_line: fid.end_line,
                start_byte,
                end_byte,
            });
            func_index.insert((fid.file.clone(), fid.name.clone(), fid.start_line), idx);
            name_index
                .entry((fid.file.clone(), fid.name.clone()))
                .or_default()
                .push(idx);
            location_index
                .entry((fid.file.clone(), fid.start_line))
